options.afterRender:
const root=context.element.querySelector('section.quality');
if(root&&!root.dataset.pagerBound){
 root.dataset.pagerBound='true';
 // Grafana sanitizes form controls before this hook. Build fixed trusted
 // controls through DOM APIs; keep HTML sanitization enabled.
 const doc=root.ownerDocument,controls=root.querySelector('[data-quality-controls]');
 const make=(tag,key,text)=>{const node=doc.createElement(tag);node.setAttribute(key,'');if(text)node.textContent=text;return node};
 const search=make('input','data-quality-filter');search.type='search';search.placeholder='Filter model or effort';search.setAttribute('aria-label','Filter model or effort');controls.append(search);
 const label=doc.createElement('label'),toggle=make('input','data-quality-all');label.className='quality-toggle';toggle.type='checkbox';label.append(toggle,doc.createTextNode(' All models'));controls.append(label);
 const pager=doc.createElement('div');pager.append(make('button','data-quality-prev','Previous'),make('span','data-quality-range'),make('button','data-quality-next','Next'));controls.append(pager);
 root.querySelectorAll('[data-quality-expand-label]').forEach(label=>{const button=make('button','data-quality-expand',label.textContent);button.className='quality-expand';button.type='button';button.setAttribute('aria-expanded','false');label.replaceWith(button)});
 const rows=[...root.querySelectorAll('tbody tr.quality-model-row')];
 const filter=root.querySelector('[data-quality-filter]'),all=root.querySelector('[data-quality-all]');
 const prev=root.querySelector('[data-quality-prev]'),next=root.querySelector('[data-quality-next]');
 const expanded=new Set();let page=0,lastWidth=0;
 function show(){
  const term=filter.value.toLowerCase().trim();
  const matches=rows.filter(row=>(all.checked||row.dataset.selected==='true')&&row.dataset.qualitySearch.toLowerCase().includes(term));
  const has=name=>matches.some(row=>row.dataset[name]==='true');
  const columns={aa:has('hasAa'),observed:has('hasObserved'),passes:has('hasObserved'),time:has('hasTime'),tokens:has('hasTokens'),quota:has('hasQuota'),findings:has('hasFindings'),source:has('hasObserved')};
  for(const [column,visible]of Object.entries(columns))root.querySelectorAll('[data-col="'+column+'"]').forEach(cell=>cell.hidden=!visible);
  root.querySelectorAll('.quality-merge').forEach(cell=>cell.hidden=!has('hasMerged'));
  root.querySelector('th[data-col="passes"]').textContent=has('hasMerged')?'Pass / merged':'Pass';
  root.querySelector('[data-quality-evidence-note]').hidden=has('hasObserved');
  root.querySelector('[data-quality-empty]').hidden=matches.length>0;
  const size=root.getBoundingClientRect().width<650?3:15;
  page=Math.max(0,Math.min(page,Math.ceil(matches.length/size)-1));
  rows.forEach(row=>{row.hidden=true});
  root.querySelectorAll('.quality-effort-detail').forEach(row=>row.hidden=true);
  matches.slice(page*size,(page+1)*size).forEach((row,index)=>{
   row.hidden=false;row.querySelector('[data-quality-rank]').textContent=page*size+index+1;const detail=row.nextElementSibling;
   if(detail&&detail.classList.contains('quality-effort-detail'))detail.hidden=!expanded.has(row.dataset.qualityKey);
  });
  root.querySelector('[data-quality-range]').textContent=matches.length?`${page*size+1}–${Math.min((page+1)*size,matches.length)} of ${matches.length}`:'No matching models';
  prev.disabled=page===0;next.disabled=(page+1)*size>=matches.length;
 }
 filter.addEventListener('input',()=>{page=0;show()});all.addEventListener('change',()=>{page=0;show()});
 prev.addEventListener('click',()=>{page--;show()});next.addEventListener('click',()=>{page++;show()});
 root.querySelectorAll('[data-quality-expand]').forEach(button=>button.addEventListener('click',()=>{
  const key=button.closest('tr').dataset.qualityKey;
  if(expanded.has(key))expanded.delete(key);else expanded.add(key);
  button.setAttribute('aria-expanded',String(expanded.has(key)));show();
 }));
 const observer=new ResizeObserver(()=>{if(!root.isConnected){observer.disconnect();return}const width=root.getBoundingClientRect().width;if(width!==lastWidth){lastWidth=width;show()}});
 observer.observe(root);show();
 return ()=>observer.disconnect();
}

options.helpers:
function qualityRows(rows){
 const groups=new Map();
 for(const row of rows||[]){
  if(!row.model||!row.provider)continue;
  const key=[row.provider,row.model,row.effort_option,row.effort].join('|');
  if(!groups.has(key))groups.set(key,{...row,values:{}});
  if(row.value!==null&&row.value!==undefined&&Number.isFinite(Number(row.value)))groups.get(key).values[row.field]=Number(row.value);
 }
 const fmt=x=>x===undefined?'—':String(Math.round(x*10)/10);
 const tok=x=>x===undefined?'—':x>=1e9?fmt(x/1e9)+'B':x>=1e6?fmt(x/1e6)+'M':x>=1e3?fmt(x/1e3)+'k':String(Math.round(x));
 const date=x=>!x?'—':new Date(x*1000).toISOString().slice(0,10);
 return [...groups.values()].sort((a,b)=>(a.values.rank??1e9)-(b.values.rank??1e9)).map(r=>{
  const v=r.values;return {...r,representative:v.representative===1,selected:r.selection==='selected',selectionReason:r.selection_reason||'',modelRank:v.model_rank??1e9,hasObserved:(v.n??0)>0,hasAA:v.aa!==undefined,hasTime:v.median_seconds!==undefined||v.seconds_per_pass!==undefined,hasTokens:v.tokens_per_pass!==undefined,hasQuota:v.quota_per_pass!==undefined,hasFindings:v.review_findings!==undefined,hasMerged:(v.merge_n??0)>0,rank:v.rank??'—',overall:fmt(v.overall),aa:fmt(v.aa),observed:fmt(v.observed),n:v.n??0,
   provisional:(v.n??0)<5,passes:v.n?v.passed+'/'+v.n:'no evidence yet',
   merges:v.merge_n?v.merged+'/'+v.merge_n:'—',
   median:v.median_seconds===undefined?'—':fmt(v.median_seconds/60)+' min',
   timePerPass:v.seconds_per_pass===undefined?'—':fmt(v.seconds_per_pass/60)+' min',
   tokens:v.tokens_per_pass===undefined?'—':tok(v.tokens_per_pass),quota:fmt(v.quota_per_pass),findings:fmt(v.review_findings),
   date:date(v.date),aaDate:v.aa!==undefined&&r.aa_date?String(r.aa_date).slice(0,10)+(r.aa_state==='stale'?' · stale':''):'',
   weight:v.observed_weight===undefined?'—':Math.round(v.observed_weight*100)+'%',
   bar:v.overall===undefined?0:Math.max(0,Math.min(100,v.overall)),
   evidenceMissing:r.evidence_state==='producer_unavailable'||r.evidence_state==='unreadable'};
 });
}
context.handlebars.registerHelper('qualityRows',qualityRows);
context.handlebars.registerHelper('qualityModels',function(rows){
 const groups=new Map();
 for(const row of qualityRows(rows)){
  const key=row.provider+'|'+row.model;
  if(!groups.has(key))groups.set(key,[]);
  groups.get(key).push(row);
 }
 return [...groups.entries()].map(([key,variants])=>{
  const best=variants.find(row=>row.representative)||variants[0];
  const measured=variants.filter(row=>row.n>0);
  const signature=row=>JSON.stringify(['n','passed','observed','merged','merge_n','median_seconds','seconds_per_pass','tokens_per_pass','quota_per_pass','review_findings'].map(field=>row.values[field]??null));
  const different=measured.length>1&&new Set(measured.map(signature)).size>1;
  return {...best,key,efforts:different?measured:[],compare:different,
   search:[best.provider,best.model,best.selection,best.selectionReason,...variants.map(row=>row.effort)].join(' ')};
 }).sort((a,b)=>a.modelRank-b.modelRank);
});

